55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	};
65	
66	const BLOCK_SIZE = 3;
67	const BLOCK_BASE_PREMIUM = 60;
68	
69	const countByType = (items: Item[]): Map<string, number> => {
70	  const counts = new Map<string, number>();
71	  for (const item of items) {
72	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
73	  }
74	  return counts;
75	};
76	
77	const basePremiumOfGroup = (type: string, count: number): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const quote = (step: QuoteStep): QuoteResult => {
81	  let policyBase = 0;
82	  for (const [type, count] of countByType(step.items)) {
83	    policyBase += basePremiumOfGroup(type, count);
84	  }
85	  const premiumBeforeRounding =
86	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE;
87	  return { premium: Math.ceil(premiumBeforeRounding) };
88	};
89	
90	export const runScenario = (scenario: Scenario): ScenarioOutput => {
91	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
92	};
